import sys
from collections import defaultdict

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m, k = readints()

    # List to store flights
    flights = []

    # Read all flights
    for _ in range(m):
        d, f, t, c = readints()
        flights.append((d, f, t, c))

    # Sort flights by departure day
    flights.sort()

    # Priority queues to manage the earliest return flights for each city
    pq = [heapq.heapify([]) for _ in range(n + 1)]

    # Dictionary to track the last day each jury member was in Metropolis
    last_in_metropolis = {i: -1 for i in range(1, n + 1)}

    total_cost = 0

    for d, f, t, c in flights:
        if f == 0:  # Flight to Metropolis
            if t in last_in_metropolis:
                last_in_metropolis[t] = d
                heapq.heappush(pq[t], d + k)
        else:  # Flight from Metropolis
            if f in last_in_metropolis:
                if d >= last_in_metropolis[f] + k:
                    total_cost += c
                else:
                    # If the flight is too early, we need to wait for the next available day
                    next_available_day = last_in_metropolis[f] + k
                    if d < next_available_day:
                        heapq.heappush(pq[f], next_available_day)
                        total_cost += c
                    else:
                        total_cost += c
                # Remove the flight from the priority queue if it's not needed anymore
                if pq[f] and pq[f][0] <= d:
                    heapq.heappop(pq[f])

    # Check if all jury members have returned home
    for i in range(1, n + 1):
        if pq[i]:
            print(-1)
            return

    print(total_cost)

if __name__ == "__main__":
    main()
